import java.util.*;
import java.io.*;
public class Text_Document_Analysis
{
    public static void main(String args[]) throws Exception
    {
        BufferedReader input=new BufferedReader(new InputStreamReader(System.in));
        // BufferedReader input=new BufferedReader(new FileReader("Text_Document_Analysis.in"));
        input.readLine();
        String data=input.readLine();
        String[] segments=data.split("\\([a-zA-Z_]*\\)");
        int maxWordLength=0;
        for(String segment: segments)
        {
            String[] words=segment.split("_+");
            for(String word: words)
                maxWordLength=Math.max(maxWordLength, word.length());
        }
        int countLetters=0;
        int letterCount=0;
        boolean insideBracket=false;
        boolean countedLetter=false;
        for(int i=0; i<data.length(); i++)
        {
            char c=data.charAt(i);
            if(c=='(')
                insideBracket=true;
            if(c==')')
            {
                countedLetter=false;
                insideBracket=false;
            }
            if(insideBracket && Character.isLetter(c))
            {
                if(countedLetter) continue;
                countLetters++;
                countedLetter=true;
            }
            if(c=='_')
                countedLetter=false;
        }
        System.out.println(maxWordLength+" "+countLetters);
    }
}
